insert into kafaa_smr_deltas (id, role_id, tech_id, rank, path_only, dims, changes_en, changes_ar, stays_en, stays_ar, skills, training, concept_role_ids, sources, benchmark_ids, status, listed, version, as_of, sort, updated_by, updated_at) values
('smrd:human-performance-specialist:tech-bwr', 'human-performance-specialist', 'tech-bwr', 2, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Performance trends and lessons learned compare several units.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. تقارن اتجاهات الأداء والدروس المستفادة بين عدة وحدات."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Human performance shifts from manual action to monitoring passive systems and avoiding complacency.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. ينتقل الأداء البشري من الإجراء اليدوي إلى مراقبة الأنظمة الخاملة وتجنب التراخي."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. Human-system interface reviews of new screens and alarms.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. مراجعات واجهة الإنسان والنظام للشاشات والإنذارات الجديدة."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Safety culture traits, independent oversight and the corrective action programme stay the same.', 'تبقى سمات ثقافة السلامة والرقابة المستقلة وبرنامج الإجراءات التصحيحية كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-regulation","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 60, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:human-performance-specialist:tech-htgr', 'human-performance-specialist', 'tech-htgr', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Several smaller reactor modules may share one plant and one control room. Performance trends and lessons learned compare several units.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. تقارن اتجاهات الأداء والدروس المستفادة بين عدة وحدات."},{"dim":"passive_safety","change":"new","text_en":"Gas-cooled designs aim to remove decay heat passively, relying on fuel and materials that tolerate high temperatures. Human performance shifts from manual action to monitoring passive systems and avoiding complacency.","text_ar":"تسعى التصاميم المبرّدة بالغاز إلى إزالة حرارة الاضمحلال بطريقة خاملة، معتمدة على وقود ومواد تتحمل درجات حرارة عالية. ينتقل الأداء البشري من الإجراء اليدوي إلى مراقبة الأنظمة الخاملة وتجنب التراخي."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. Human-system interface reviews of new screens and alarms.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. مراجعات واجهة الإنسان والنظام للشاشات والإنذارات الجديدة."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are passive safety; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في السلامة الخاملة، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Safety culture traits, independent oversight and the corrective action programme stay the same.', 'تبقى سمات ثقافة السلامة والرقابة المستقلة وبرنامج الإجراءات التصحيحية كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-regulation","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-hydrogen"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 61, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:ecp-officer:tech-bwr', 'ecp-officer', 'tech-bwr', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Concern channels serve crews spread across several units.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. تخدم قنوات المخاوف أطقماً موزعة على عدة وحدات."}]'::jsonb, 'Small boiling water reactor: for this role multi-module operation adapts; the rest stays close to today. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: في هذا الدور يتكيف كل من التشغيل متعدد الوحدات، ويبقى الباقي قريباً مما هو عليه اليوم. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Confidentiality, non-retaliation and the right to raise a concern stay the same.', 'تبقى السرية وعدم الانتقام والحق في إثارة المخاوف كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr-x"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 62, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:ecp-officer:tech-micro', 'ecp-officer', 'tech-micro', 2, false, '[{"dim":"multi_module","change":"adapts","text_en":"Many small transportable units rather than one plant. Concern channels serve crews spread across several units.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. تخدم قنوات المخاوف أطقماً موزعة على عدة وحدات."}]'::jsonb, 'Microreactors: for this role multi-module operation adapts; the rest stays close to today. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: في هذا الدور يتكيف كل من التشغيل متعدد الوحدات، ويبقى الباقي قريباً مما هو عليه اليوم. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Confidentiality, non-retaliation and the right to raise a concern stay the same.', 'تبقى السرية وعدم الانتقام والحق في إثارة المخاوف كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr-x"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"pathway","ref":"pw-adv-micro-l1"},{"kind":"course","ref":"c-fs-remote"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 63, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:ecp-officer:tech-intl', 'ecp-officer', 'tech-intl', 3, false, '[{"dim":"delivery","change":"adapts","text_en":"Project delivery abroad, investment and owner''s-engineer work for partners. Concern channels for staff working with partners abroad.","text_ar":"تنفيذ المشاريع في الخارج والاستثمار وأعمال مهندس المالك للشركاء. قنوات المخاوف للموظفين العاملين مع الشركاء في الخارج."}]'::jsonb, 'International projects: for this role project delivery adapts; the rest stays close to today. Planning assumption; no deployment decision implied.', 'المشاريع الدولية: في هذا الدور يتكيف كل من تنفيذ المشاريع، ويبقى الباقي قريباً مما هو عليه اليوم. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Confidentiality, non-retaliation and the right to raise a concern stay the same.', 'تبقى السرية وعدم الانتقام والحق في إثارة المخاوف كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-en-01-project","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr-x"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"nucleareurope-match","label":"nucleareurope · MATCH programme: a tool for nuclear capacity building in France","url":"https://www.nucleareurope.eu/blog/highlight-of-the-month/match-program-a-tool-for-nuclear-capacity-building-in-france/","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 64, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:industrial-health-safety-officer:tech-fast', 'industrial-health-safety-officer', 'tech-fast', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"Fleet concepts with several units change how operations and support are organised. Emergency plans and drills cover several smaller units.","text_ar":"تغيّر مفاهيم الأساطيل متعددة الوحدات طريقة تنظيم التشغيل والدعم. تغطي خطط الطوارئ والتمارين عدة وحدات أصغر."},{"dim":"passive_safety","change":"new","text_en":"Fast-reactor concepts rely on passive heat removal through the coolant''s natural circulation. Longer coping times change the timeline of an emergency response.","text_ar":"تعتمد مفاهيم المفاعلات السريعة على إزالة الحرارة بطريقة خاملة عبر الدوران الطبيعي للمبرد. تغيّر فترات التحمل الأطول الجدول الزمني للاستجابة للطوارئ."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation designed for liquid-metal coolant and a fast neutron spectrum. Remote monitoring feeds the emergency organisation.","text_ar":"أجهزة مصممة لمبرد معدني سائل وطيف نيوتروني سريع. تغذي المراقبة عن بعد منظمة الطوارئ."},{"dim":"systems","change":"new","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. New industrial hazards from different coolants and materials.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. مخاطر صناعية جديدة من المبردات والمواد المختلفة."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Hazard identification, permits, drills and the emergency organisation''s roles stay the same.', 'يبقى تحديد المخاطر والتصاريح والتمارين وأدوار منظمة الطوارئ كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 65, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:industrial-health-safety-officer:tech-msr', 'industrial-health-safety-officer', 'tech-msr', 2, false, '[{"dim":"multi_module","change":"adapts","text_en":"Modular plant concepts with several units. Emergency plans and drills cover several smaller units.","text_ar":"مفاهيم محطات معيارية بعدة وحدات. تغطي خطط الطوارئ والتمارين عدة وحدات أصغر."},{"dim":"passive_safety","change":"new","text_en":"Molten salt concepts rely on passive features of the salt and the design to remove heat. Longer coping times change the timeline of an emergency response.","text_ar":"تعتمد مفاهيم الأملاح المنصهرة على الخصائص الخاملة للملح والتصميم لإزالة الحرارة. تغيّر فترات التحمل الأطول الجدول الزمني للاستجابة للطوارئ."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation and sampling designed for hot salt systems. Remote monitoring feeds the emergency organisation.","text_ar":"أجهزة وأخذ عينات مصممة لأنظمة الأملاح الساخنة. تغذي المراقبة عن بعد منظمة الطوارئ."},{"dim":"systems","change":"new","text_en":"Salt chemistry and materials replace water chemistry. New industrial hazards from different coolants and materials.","text_ar":"تحل كيمياء الأملاح وموادها محل كيمياء الماء. مخاطر صناعية جديدة من المبردات والمواد المختلفة."}]'::jsonb, 'Molten salt: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'مفاعلات الأملاح المنصهرة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Hazard identification, permits, drills and the emergency organisation''s roles stay the same.', 'يبقى تحديد المخاطر والتصاريح والتمارين وأدوار منظمة الطوارئ كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 66, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:industrial-health-safety-officer:tech-bwr', 'industrial-health-safety-officer', 'tech-bwr', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Emergency plans and drills cover several smaller units.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. تغطي خطط الطوارئ والتمارين عدة وحدات أصغر."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Longer coping times change the timeline of an emergency response.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. تغيّر فترات التحمل الأطول الجدول الزمني للاستجابة للطوارئ."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. Remote monitoring feeds the emergency organisation.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. تغذي المراقبة عن بعد منظمة الطوارئ."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. New industrial hazards from different coolants and materials.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. مخاطر صناعية جديدة من المبردات والمواد المختلفة."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Hazard identification, permits, drills and the emergency organisation''s roles stay the same.', 'يبقى تحديد المخاطر والتصاريح والتمارين وأدوار منظمة الطوارئ كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 67, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:fire-protection:tech-fast', 'fire-protection', 'tech-fast', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"Fleet concepts with several units change how operations and support are organised. Emergency plans and drills cover several smaller units.","text_ar":"تغيّر مفاهيم الأساطيل متعددة الوحدات طريقة تنظيم التشغيل والدعم. تغطي خطط الطوارئ والتمارين عدة وحدات أصغر."},{"dim":"passive_safety","change":"new","text_en":"Fast-reactor concepts rely on passive heat removal through the coolant''s natural circulation. Longer coping times change the timeline of an emergency response.","text_ar":"تعتمد مفاهيم المفاعلات السريعة على إزالة الحرارة بطريقة خاملة عبر الدوران الطبيعي للمبرد. تغيّر فترات التحمل الأطول الجدول الزمني للاستجابة للطوارئ."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation designed for liquid-metal coolant and a fast neutron spectrum. Remote monitoring feeds the emergency organisation.","text_ar":"أجهزة مصممة لمبرد معدني سائل وطيف نيوتروني سريع. تغذي المراقبة عن بعد منظمة الطوارئ."},{"dim":"systems","change":"new","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. New industrial hazards from different coolants and materials.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. مخاطر صناعية جديدة من المبردات والمواد المختلفة."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Hazard identification, permits, drills and the emergency organisation''s roles stay the same.', 'يبقى تحديد المخاطر والتصاريح والتمارين وأدوار منظمة الطوارئ كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 68, 'p-training-mgr', '2026-10-11T08:00:00Z'),
